INSERT INTO settings (key, value) VALUES ('payments', '{"sslcommerz":true,"bkash_direct":false,"manual":true,"manual_numbers":{"bkash":"","nagad":"","rocket":""},"manual_note_bn":"টাকা পাঠিয়ে ট্রানজেকশন আইডি (TrxID) এবং যে নম্বর থেকে পাঠিয়েছেন সেটি জমা দিন। যাচাই শেষে আপনার ক্লাস চালু হবে।","manual_note_en":"Send the amount, then submit the transaction ID (TrxID) and the number you paid from. Your class opens as soon as we verify it."}');
INSERT INTO settings (key, value) VALUES ('policies', '{"refund_bn":"আমাদের রিফান্ড নীতি শীঘ্রই এখানে প্রকাশ করা হবে। কেনার আগে কোনো প্রশ্ন থাকলে অনুগ্রহ করে আমাদের সাথে যোগাযোগ করুন।","refund_en":"Our refund policy will be published here soon. If you have any question before buying, please contact us first.","privacy_bn":"আমরা শুধু ক্লাস সরবরাহ, পেমেন্ট যাচাই এবং সহায়তার জন্য আপনার নাম, ইমেইল ও ফোন নম্বর ব্যবহার করি। আপনার তথ্য তৃতীয় পক্ষের কাছে বিক্রি করা হয় না।","privacy_en":"We use your name, email and phone number only to deliver classes, verify payments and give support. We never sell your data to third parties.","terms_bn":"ক্লাসের কনটেন্ট শুধুমাত্র ভর্তি হওয়া শিক্ষার্থীর ব্যক্তিগত শেখার জন্য। অনুমতি ছাড়া ভিডিও বা রেসিপি শেয়ার, বিক্রি বা পুনঃপ্রকাশ করা যাবে না।","terms_en":"Class content is for the personal learning of the enrolled student only. Videos and recipes may not be shared, resold or republished without permission."}');
INSERT INTO settings (key, value) VALUES ('about', '{"bn":"মাওয়াহ একাডেমি রান্না ও বেকিংয়ের একটি অনলাইন একাডেমি। আমাদের ক্লাসগুলো ঘরে বসে ধাপে ধাপে শেখার জন্য সাজানো — কেক, মিষ্টি, ফাস্টফুড, বিরিয়ানি থেকে শুরু করে ফ্রোজেন ফুড বিজনেস পর্যন্ত।","en":"MAWAH Academy is an online cooking and baking academy. Our classes are arranged so you can learn step by step from home — from cakes, mishti, fast food and biryani to frozen food business."}');
